const staticData = $getWorkflowStaticData('global');

staticData.customers = [
  {
    customerId: "CUST-001",
    name: "Acme Corp",
    balance: 1200,
    creditLimit: 5000
  },
  {
    customerId: "CUST-002",
    name: "Globex Inc",
    balance: 450,
    creditLimit: 500
  }
];

staticData.orders = [];
staticData.orderItems = [];

return [
  {
    json: {
      status: "DATABASE_INITIALIZED",
      tables: [
        "customers",
        "orders",
        "order_items"
      ],
      customerCount: staticData.customers.length,
      timestamp: new Date().toISOString()
    }
  }
];

return [
  {
    json: {
      orderId: "ORD-DB-5001",
      customerId: "CUST-001",
      orderDate: new Date().toISOString(),
      lineItems: [
        {
          sku: "SKU-SRV-01",
          description: "Cloud Managed Server",
          quantity: 2,
          unitPrice: 450
        },
        {
          sku: "SKU-LIC-02",
          description: "Enterprise Security Seat",
          quantity: 5,
          unitPrice: 75
        }
      ]
    }
  }
];

const order = $input.item.json;

const orderTotal = order.lineItems.reduce(
  (sum, item) => sum + item.quantity * item.unitPrice,
  0
);

const orderHeader = {
  orderId: order.orderId,
  customerId: order.customerId,
  orderDate: order.orderDate,
  totalAmount: orderTotal,
  status: "PENDING"
};

return {
  json: {
    ...order,
    orderHeader,
    transactionStatus: "HEADER_STAGED"
  }
};

const order = $input.item.json;

const orderItems = order.lineItems.map((item, index) => ({
  orderItemId: `${order.orderId}-ITEM-${index + 1}`,
  orderId: order.orderId,
  sku: item.sku,
  description: item.description,
  quantity: item.quantity,
  unitPrice: item.unitPrice,
  lineTotal: item.quantity * item.unitPrice
}));

const calculatedTotal = orderItems.reduce(
  (sum, item) => sum + item.lineTotal,
  0
);

if (calculatedTotal !== order.orderHeader.totalAmount) {
  throw new Error("Order total does not match item totals");
}

return {
  json: {
    ...order,
    orderItems,
    calculatedTotal,
    transactionStatus: "ITEMS_STAGED"
  }
};

const order = $input.item.json;

// Customer record from our simulated database
const customers = [
  {
    customerId: "CUST-001",
    name: "Acme Corp",
    balance: 1200,
    creditLimit: 5000
  },
  {
    customerId: "CUST-002",
    name: "Globex Inc",
    balance: 450,
    creditLimit: 500
  }
];

const customer = customers.find(
  c => c.customerId === order.customerId
);

if (!customer) {
  return {
    json: {
      ...order,
      transactionSucceeded: false,
      transactionStatus: "ROLLBACK_REQUIRED",
      reason: "Customer not found"
    }
  };
}

const orderAmount = order.calculatedTotal;
const previousBalance = customer.balance;
const updatedBalance = previousBalance + orderAmount;

const withinCreditLimit =
  updatedBalance <= customer.creditLimit;

return {
  json: {
    ...order,
    customerName: customer.name,
    previousBalance,
    orderAmount,
    updatedBalance: withinCreditLimit
      ? updatedBalance
      : previousBalance,
    creditLimit: customer.creditLimit,
    transactionSucceeded: withinCreditLimit,
    transactionStatus: withinCreditLimit
      ? "READY_TO_COMMIT"
      : "ROLLBACK_REQUIRED",
    reason: withinCreditLimit
      ? "Credit limit validation passed"
      : "Credit limit exceeded"
  }
};

const order = $input.item.json;

return {
  json: {
    auditEvent: "TRANSACTION_ROLLBACK",
    transactionStatus: "ROLLED_BACK",
    orderId: order.orderId,
    customerId: order.customerId,
    orderAmount: order.orderAmount,
    previousBalance: order.previousBalance,
    creditLimit: order.creditLimit,
    reason: order.reason || "Transaction validation failed",
    message: "Transaction rejected. No changes committed.",
    loggedAt: new Date().toISOString()
  }
};

const data = $input.item.json;

const fullOrder = {
  orderId: data.orderId,
  customerId: data.customerId,
  customerName: data.customerName,
  orderDate: data.orderDate,
  orderStatus: "COMMITTED",
  orderItems: data.orderItems,
  totalItems: data.orderItems.length,
  totalAmount: data.calculatedTotal,
  previousBalance: data.previousBalance,
  updatedBalance: data.updatedBalance,
  creditLimit: data.creditLimit,
  transactionStatus: "COMMITTED"
};

return {
  json: fullOrder
};

const order = $input.item.json;

// Validate order item totals
const itemTotal = order.orderItems.reduce(
  (sum, item) => sum + Number(item.lineTotal),
  0
);

const totalMatches = itemTotal === order.totalAmount;

const creditValid =
  order.updatedBalance <= order.creditLimit;

const transactionValid =
  order.transactionStatus === "COMMITTED" &&
  totalMatches &&
  creditValid;

return {
  json: {
    auditStatus: transactionValid
      ? "TRANSACTION_VERIFIED"
      : "VALIDATION_FAILED",

    orderId: order.orderId,
    customerId: order.customerId,
    customerName: order.customerName,

    transactionStatus: order.transactionStatus,

    totalItems: order.totalItems,
    orderTotal: order.totalAmount,
    calculatedItemTotal: itemTotal,

    totalMatches,
    creditValid,
    transactionValid,

    previousBalance: order.previousBalance,
    updatedBalance: order.updatedBalance,
    creditLimit: order.creditLimit,

    auditTimestamp: new Date().toISOString()
  }
};
